def v3_7_2_rank_family_candidates(
    *,
    query_text: str,
    candidate_rows: Sequence[Mapping[str, Any]],
    base_scores: Sequence[Any],
    top_k: int,
) -> list[tuple[int, float]]:
    query_tokens = v3_7_2_rerank_tokens(query_text)
    scored: list[tuple[int, float, float, int]] = []
    for index, row in enumerate(candidate_rows):
        faiss_row_id = v3_7_2_candidate_faiss_row_id(row)
        base_score = float(base_scores[index])
        rerank_score = v3_7_2_manifest_lexical_rerank_score(
            query_tokens=query_tokens,
            candidate_row=row,
        )
        scored.append((faiss_row_id, base_score + rerank_score, rerank_score, index))
    scored.sort(key=lambda item: (-item[1], -item[2], item[3]))
    return [(faiss_row_id, score) for faiss_row_id, score, _rerank, _index in scored[:top_k]]


def v3_7_2_candidate_faiss_row_id(row: Mapping[str, Any]) -> int:
    value = row.get("faiss_row_id")
    if value is None or value == "":
        return -1
    return int(value)


def v3_7_2_manifest_lexical_rerank_score(
    *,
    query_tokens: set[str],
    candidate_row: Mapping[str, Any],
) -> float:
    candidate_text = v3_7_2_manifest_rerank_text(candidate_row)
    candidate_tokens = v3_7_2_rerank_tokens(candidate_text)
    overlap = query_tokens & candidate_tokens
    score = 0.0
    if overlap:
        score += sum(v3_7_2_rerank_token_weight(token) for token in overlap) / max(6.0, len(query_tokens) + 4.0)
    lowered_candidate = candidate_text.lower()
    lowered_query_tokens = {token.lower() for token in query_tokens}
    score += v3_7_2_structured_field_match_bonus(lowered_query_tokens, lowered_candidate, candidate_row)
    return score


def v3_7_2_manifest_rerank_text(candidate_row: Mapping[str, Any]) -> str:
    return "\n".join(
        official.clean(candidate_row.get(key))
        for key in ("bm25_text", "display_text", "embedding_text", "source_identity", "workbook_id", "document_id")
        if official.clean(candidate_row.get(key))
    )


def v3_7_2_rerank_tokens(text: Any) -> set[str]:
    lowered = official.clean(text).lower()
    tokens: set[str] = set()
    for year, month in re.findall(r"(\d{4})\s*년\s*(\d{1,2})\s*월", lowered):
        tokens.add(f"{year}{int(month):02d}")
    for year, month in re.findall(r"(\d{4})[.\-/](\d{1,2})", lowered):
        tokens.add(f"{year}{int(month):02d}")
    for token in re.findall(r"[0-9a-z가-힣]+", lowered):
        if len(token) == 1 and not token.isdigit():
            continue
        if token in V3_7_2_RERANK_TOKEN_STOPWORDS:
            continue
        tokens.add(token)
        for normalized in v3_7_2_korean_particle_variants(token):
            if normalized not in V3_7_2_RERANK_TOKEN_STOPWORDS:
                tokens.add(normalized)
    return tokens


def v3_7_2_korean_particle_variants(token: str) -> set[str]:
    variants = set()
    for suffix in V3_7_2_RERANK_PARTICLE_SUFFIXES:
        if token.endswith(suffix) and len(token) > len(suffix) + 1:
            variants.add(token[: -len(suffix)])
    return variants


def v3_7_2_rerank_token_weight(token: str) -> float:
    if re.fullmatch(r"\d{6}", token):
        return 2.0
    if token.isdigit():
        return 1.5
    if len(token) >= 6:
        return 3.0
    if len(token) >= 4:
        return 2.0
    return 1.0


def v3_7_2_structured_field_match_bonus(
    query_tokens: set[str],
    lowered_candidate_text: str,
    candidate_row: Mapping[str, Any],
) -> float:
    family = official.clean(candidate_row.get("source_family")).upper()
    score = 0.0
    for token in query_tokens:
        if len(token) >= 6 and token in lowered_candidate_text:
            score += 0.35
    if family == "XLSX":
        for field_name in ("row_label", "column_label", "target_column", "normalized_value"):
            score += v3_7_2_field_specific_bonus(query_tokens, lowered_candidate_text, field_name)
        if "cell=" in lowered_candidate_text and (
            "row_label=" in lowered_candidate_text or "target_column=" in lowered_candidate_text
        ):
            score += 0.20
        if (
            "range=" in lowered_candidate_text
            and "cell=" not in lowered_candidate_text
            and "target_column=" not in lowered_candidate_text
        ):
            score -= 0.25
    elif family == "PDF":
        score += v3_7_2_field_specific_bonus(query_tokens, lowered_candidate_text, "matched_text")
        if "목 차" in lowered_candidate_text or "목차" in lowered_candidate_text:
            score -= 0.15
    return score


def v3_7_2_field_specific_bonus(
    query_tokens: set[str],
    lowered_candidate_text: str,
    field_name: str,
) -> float:
    marker = f"{field_name}="
    marker_index = lowered_candidate_text.find(marker)
    if marker_index < 0:
        return 0.0
    field_window = lowered_candidate_text[marker_index : marker_index + 400]
    return sum(0.30 for token in query_tokens if len(token) >= 2 and token in field_window)


def v3_7_2_target_maps_from_search_view_rows(
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, dict[str, list[Mapping[str, Any]]]]:
    by_parent: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    by_search: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    by_locator: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for row in rows:
        parent_source_unit_id = official.clean(row.get("parent_source_unit_id"))
        if parent_source_unit_id:
            by_parent[parent_source_unit_id].append(row)
        search_unit_id = official.clean(row.get("parent_search_unit_id"))
        if search_unit_id:
            by_search[search_unit_id].append(row)
        locator_fingerprint = official.clean(row.get("locator_fingerprint"))
        if locator_fingerprint:
            by_locator[locator_fingerprint].append(row)
    return {
        "target_rows_by_parent_source_unit_id": dict(by_parent),
        "target_rows_by_search_unit_id": dict(by_search),
        "target_rows_by_locator_fingerprint": dict(by_locator),
    }


def v3_7_2_top_bucket(counts: Mapping[str, Any]) -> str:
    ranked = sorted(
        ((bucket, int(count or 0)) for bucket, count in counts.items()),
        key=lambda item: (-item[1], item[0]),
    )
    if not ranked or ranked[0][1] <= 0:
        return "none"
    return ranked[0][0]


def v3_7_2_next_fix_for_bucket(*, track: str, bucket: str) -> str:
    if bucket == "none":
        return f"{track}: keep as contract-pass baseline; no dominant failure bucket in this smoke."
    fixes = {
        "search_miss": "inspect SearchView query text and source-family coverage for missed top-k retrieval",
        "source_atom_missing": "repair SearchView source_atom_id registry pointers before any metric work",
        "source_atom_blocked": "inspect blocked SourceAtom policy reason and decide whether runtime evidence is allowed",
        "locator_incomplete": "repair track locator fields in SourceAtom canonical citation payload",
        "evidence_bundle_render_failed": "patch EvidenceBundle adapter for hydrated SourceAtoms",
        "citation_render_failed": "patch citation renderer for the hydrated SourceAtom family",
        "snapshot_only": "rank snapshot-only rows that can be upgraded to runtime evidence",
        "adapter_missing": "add or reconnect the track adapter for SearchView to SourceAtom hydration",
        "track_mismatch": "inspect retrieval routing and per-track candidate mix after contract survival is stable",
    }
    return f"{track}: {fixes.get(bucket, 'inspect contract failure bucket')}"


def v3_7_2_next_fixes_ranked_by_impact(
    *,
    failure_buckets: Mapping[str, Any],
    silver_overlay: Mapping[str, Any],
) -> list[dict[str, Any]]:
    counts = as_mapping(failure_buckets.get("failure_bucket_counts"))
    detail_counts = as_mapping(failure_buckets.get("detail_failure_bucket_counts"))
    ranked = [
        {
            "rank_basis": "contract_failure_reduction",
            "bucket": bucket,
            "impact_count": int(count),
            "next_fix": v3_7_2_next_fix_for_bucket(track="ALL", bucket=bucket),
        }
        for bucket, count in sorted(counts.items(), key=lambda item: (-int(item[1] or 0), item[0]))
        if int(count or 0) > 0
    ]
    ranked.extend(
        {
            "rank_basis": "locator_or_adapter_gap",
            "bucket": official.clean(bucket),
            "impact_count": int(count),
            "next_fix": f"ALL: repair locator/adapter gap `{official.clean(bucket)}` before promotion discussion",
        }
        for bucket, count in sorted(detail_counts.items(), key=lambda item: (-int(item[1] or 0), item[0]))[:10]
        if int(count or 0) > 0
    )
    if not ranked:
        ranked.append(
            {
                "rank_basis": "contract_failure_reduction",
                "bucket": "none",
                "impact_count": 0,
                "next_fix": "Keep comparable live measurement closed until this contract smoke is accepted.",
            }
        )
    return ranked[:12]


def v3_7_2_counter_ranked(counter: Counter[str], *, limit: int = 12) -> list[dict[str, Any]]:
    return [
        {"key": key, "count": int(count)}
        for key, count in sorted(counter.items(), key=lambda item: (-item[1], item[0]))[:limit]
        if int(count) > 0
    ]


